module edge_detect(
    input clk, input rst_n, input a,
    output reg rise, output reg down
);
    reg a_delay;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_delay <= 0;
            rise <= 0;
            down <= 0;
        end else begin
            a_delay <= a;
            if (a && !a_delay) begin
                rise <= 1;
                down <= 0;
            end else if (!a && a_delay) begin
                rise <= 0;
                down <= 1;
            end else begin
                rise <= 0;
                down <= 0;
            end
        end
    end
endmodule
